<?php use Namira\CallUI;$prefix=$prefix??'answers';$values=$values??[];$preview=$preview??false; ?>
<div class="fields call-fields"><?php foreach($fields as $f):if(empty($f['active']))continue;$key=$f['key'];$name=$prefix.'['.$key.']';$v=$values[$key]??null;$fid='cf_'.substr(hash('sha256',$prefix.($workId??0).$key),0,16); ?>
<div class="field <?= in_array($f['type'],['textarea','file','multi'],true)?'full':'' ?>" data-call-field="<?= e($key) ?>"><label for="<?= $fid ?>"><?= e($f['label']) ?><?= $f['required']?' *':' (اختیاری)' ?></label><?php if($f['help']!==''): ?><small class="hint"><?= e($f['help']) ?></small><?php endif ?>
<?php if($f['type']==='textarea'): ?><textarea id="<?= $fid ?>" name="<?= e($name) ?>" rows="5" maxlength="<?= $f['max_length'] ?>"><?= e($v??'') ?></textarea>
<?php elseif($f['type']==='select'): ?><select id="<?= $fid ?>" name="<?= e($name) ?>"><option value="">انتخاب نشده</option><?php foreach($f['options'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= (string)$v===(string)$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select>
<?php elseif($f['type']==='multi'): ?><input type="hidden" name="<?= e($name) ?>" value=""><div class="call-checks"><?php foreach($f['options'] as $value=>$label): ?><label><input type="checkbox" name="<?= e($name) ?>[]" value="<?= e($value) ?>" <?= in_array((string)$value,array_map('strval',(array)$v),true)?'checked':'' ?>><?= e($label) ?></label><?php endforeach ?></div>
<?php elseif($f['type']==='checkbox'): ?><input type="hidden" name="<?= e($name) ?>" value="0"><label class="call-check"><input id="<?= $fid ?>" type="checkbox" name="<?= e($name) ?>" value="1" <?= $v?'checked':'' ?>><?= e($f['label']) ?></label>
<?php elseif($f['type']==='file'): ?><?php if(!$preview):view('call-upload-field',['db'=>$db,'batch'=>$batch,'workId'=>$workId??null,'fieldKey'=>($filePrefix??'').$key,'inputName'=>$name,'policy'=>$policy,'label'=>$f['label']]);else: ?><input type="file" disabled aria-label="<?= e($f['label']) ?>"><small>پیش‌نمایش؛ بارگذاری در فرم واقعی فعال است.</small><?php endif ?>
<?php else: ?><input id="<?= $fid ?>" name="<?= e($name) ?>" value="<?= e($v??'') ?>" type="<?= $f['type']==='date'?'date':($f['type']==='number'?'text':'text') ?>" <?= $f['type']==='number'?'inputmode="decimal"':'' ?> maxlength="<?= $f['max_length'] ?>">
<?php endif ?><small class="call-field-error" data-call-field-error role="alert"></small></div><?php endforeach ?></div>